import{_ as e,o as a,c as n,a2 as i}from"./chunks/framework.XXezeKOl.js";const h=JSON.parse('{"title":"什么是上下文工程","description":"从提示词工程到上下文工程：Agent 每一步该让模型看到什么、不该看到什么，以及写入、选择、压缩、隔离四类基本策略。","frontmatter":{"title":"什么是上下文工程","description":"从提示词工程到上下文工程：Agent 每一步该让模型看到什么、不该看到什么，以及写入、选择、压缩、隔离四类基本策略。"},"headers":[],"relativePath":"guide/07-context-engineering/overview.md","filePath":"guide/07-context-engineering/overview.md","lastUpdated":null}'),r={name:"guide/07-context-engineering/overview.md"};function s(l,t,o,d,p,u){return a(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="什么是上下文工程" tabindex="-1">什么是上下文工程 <a class="header-anchor" href="#什么是上下文工程" aria-label="Permalink to &quot;什么是上下文工程&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>理解上下文工程的定义，以及它和提示词工程的关系</li><li>认识一次模型调用的上下文由哪些部分组成</li><li>知道上下文&quot;越多越好&quot;为什么是错的：成本、延迟和注意力稀释</li><li>掌握写入、选择、压缩、隔离四类策略，并知道本模块后续文章分别对应哪一类</li></ul></div><h2 id="从提示词到上下文" tabindex="-1">从提示词到上下文 <a class="header-anchor" href="#从提示词到上下文" aria-label="Permalink to &quot;从提示词到上下文&quot;">​</a></h2><p><a href="/guide/04-prompt/basics">提示词工程</a> 关注的是&quot;怎么写好一段指令&quot;。做聊天机器人时这基本够用：系统提示词写好，用户问一句答一句。</p><p>到了 Agent 场景，情况变了。一个 Agent 跑 20 步，每一步发给模型的内容都不一样：系统提示词、十几个工具的定义、用户最初的需求、前面每一步的工具调用和结果、从知识库检索到的文档、长期记忆里的用户偏好……这些加起来很容易达到几万甚至几十万 Token。提示词只是其中很小的一部分。</p><p>上下文工程（Context Engineering）就是在每一次模型调用前，决定上下文窗口里放什么、怎么放、放多少的工程实践。一句话概括：在有限的窗口里，给模型恰好足够完成下一步的信息。</p><table tabindex="0"><thead><tr><th>维度</th><th>提示词工程</th><th>上下文工程</th></tr></thead><tbody><tr><td>关注对象</td><td>指令怎么写</td><td>窗口里的全部内容</td></tr><tr><td>时间尺度</td><td>一次调用</td><td>多轮、多步、跨会话</td></tr><tr><td>主要手段</td><td>措辞、结构、示例</td><td>检索、裁剪、摘要、缓存、记忆、子 Agent</td></tr><tr><td>典型问题</td><td>模型没理解意图</td><td>信息缺失、信息过载、信息过期、成本过高</td></tr><tr><td>关系</td><td>上下文工程的一个子集</td><td>包含提示词工程</td></tr></tbody></table><h2 id="上下文由什么组成" tabindex="-1">上下文由什么组成 <a class="header-anchor" href="#上下文由什么组成" aria-label="Permalink to &quot;上下文由什么组成&quot;">​</a></h2><p>以一个处于第 8 步的客服 Agent 为例，一次调用的上下文大致是这样的：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─ context window ──────────────────────────────────────┐</span></span>
<span class="line"><span>│ [1] system prompt        role, rules, output format    │  stable</span></span>
<span class="line"><span>│ [2] tool definitions     12 tools, JSON Schema         │  stable</span></span>
<span class="line"><span>│ [3] long-term memory     user profile, preferences     │  per user</span></span>
<span class="line"><span>│ [4] retrieved docs       top-5 chunks from RAG         │  per step</span></span>
<span class="line"><span>│ [5] history              user / assistant turns        │  growing</span></span>
<span class="line"><span>│ [6] tool calls/results   7 steps of observations       │  growing fast</span></span>
<span class="line"><span>│ [7] current input        the latest user message       │  per step</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>不同部分的特点差异很大：</p><ul><li>[1][2] 几乎不变，适合放在最前面并利用 <a href="/guide/07-context-engineering/prompt-caching">Prompt Caching</a>。</li><li>[3][4] 每次都要&quot;选&quot;：选哪些记忆、检索哪些文档，选错了就是噪音，见 <a href="/guide/09-rag/overview">RAG 全景</a> 和 <a href="/guide/08-memory/memory-strategy">记忆读写策略与方案对比</a>。</li><li>[5][6] 随步数不断增长，而且往往是窗口最大的消耗者。一次网页抓取、一次数据库查询就可能返回几千 Token。这是 <a href="/guide/07-context-engineering/window-management">上下文窗口管理</a> 和 <a href="/guide/07-context-engineering/compression">压缩与摘要</a> 主要处理的对象。</li></ul><h2 id="为什么不能把所有东西都塞进去" tabindex="-1">为什么不能把所有东西都塞进去 <a class="header-anchor" href="#为什么不能把所有东西都塞进去" aria-label="Permalink to &quot;为什么不能把所有东西都塞进去&quot;">​</a></h2><p>模型的窗口越来越大，很自然的想法是&quot;全放进去，让模型自己挑&quot;。这在实践中有三个问题。</p><p>成本和延迟。Agent 每一步都会重发整个上下文。上下文翻倍，每一步的输入成本和首 Token 延迟都随之上升，而步数一多，总成本近似按步数的平方增长。</p><p>注意力稀释。窗口能装下，不代表模型能用好。研究发现，相关信息放在长上下文中间位置时，模型的利用效果明显低于放在开头或结尾（&quot;Lost in the Middle&quot;）。无关内容越多，模型越容易被带偏，这种随上下文变长而出现的质量下降有时被称为&quot;上下文腐化&quot;（context rot）。</p><p>错误累积。上下文里的内容会被模型当作事实：</p><table tabindex="0"><thead><tr><th>问题</th><th>表现</th><th>例子</th></tr></thead><tbody><tr><td>污染</td><td>早期的错误信息被后续步骤反复引用</td><td>第 2 步的幻觉结论，第 10 步还在当作依据</td></tr><tr><td>干扰</td><td>大量无关内容让模型偏离当前任务</td><td>一份 5000 字的日志里只有一行有用</td></tr><tr><td>混淆</td><td>相似信息太多，模型选错</td><td>30 个功能相近的工具，调用了错误的那个</td></tr><tr><td>冲突</td><td>上下文中的信息互相矛盾</td><td>旧版文档和新版文档同时被检索出来</td></tr></tbody></table><p>所以上下文工程的目标不是&quot;最多&quot;，而是&quot;信噪比最高&quot;。</p><h2 id="四类基本策略" tabindex="-1">四类基本策略 <a class="header-anchor" href="#四类基本策略" aria-label="Permalink to &quot;四类基本策略&quot;">​</a></h2><p>业界对上下文工程的手段有不少归纳方式，一种常见的划分是四类：写入（Write）、选择（Select）、压缩（Compress）、隔离（Isolate）。</p><table tabindex="0"><thead><tr><th>策略</th><th>核心思想</th><th>典型手段</th><th>本站相关文章</th></tr></thead><tbody><tr><td>写入</td><td>把信息存到窗口之外，需要时再取</td><td>草稿本 / 待办文件、长期记忆、把大结果存文件只返回路径</td><td><a href="/guide/08-memory/long-term">长期记忆与用户画像</a></td></tr><tr><td>选择</td><td>只把和当前步骤相关的内容放进来</td><td>RAG 检索、记忆召回、按任务动态挑选工具</td><td><a href="/guide/09-rag/hybrid-rerank">混合检索与重排</a></td></tr><tr><td>压缩</td><td>用更少的 Token 表达同样的信息</td><td>截断工具结果、裁剪旧消息、对历史做摘要</td><td><a href="/guide/07-context-engineering/window-management">上下文窗口管理</a>、<a href="/guide/07-context-engineering/compression">压缩与摘要</a></td></tr><tr><td>隔离</td><td>把子任务放进独立的上下文</td><td>子 Agent、沙箱执行环境、分离的状态字段</td><td><a href="/guide/12-multi-agent/state-sharing">状态共享与通信</a></td></tr></tbody></table><p>几个具体例子：</p><ul><li>写入：<a href="/guide/13-coding-agent/coding-agents">Coding Agent</a> 常常维护一个待办清单文件，每完成一项就更新它。即使历史被压缩，计划依然完整保存在文件里，随时可以读回来。</li><li>选择：一个有 50 个工具的 Agent，先根据用户问题检索出最相关的 8 个工具再交给模型，比把 50 个全部塞进去更准确，也更省 Token。</li><li>压缩：工具返回一个 2 万行的日志，只保留错误行和前后几行；对话超过 30 轮时，把前 20 轮总结成一段摘要。</li><li>隔离：主 Agent 让一个子 Agent 去&quot;阅读这 10 篇文档并总结要点&quot;。子 Agent 消耗了 10 万 Token 的上下文，返回给主 Agent 的只有 1000 Token 的结论。</li></ul><p>此外，提示词缓存不减少 Token 数量，但能显著降低重复前缀的成本和延迟。它对上下文的&quot;排列顺序&quot;有要求，因此也是上下文工程的一部分，见 <a href="/guide/07-context-engineering/prompt-caching">Prompt Caching</a>。</p><h2 id="一份上下文设计清单" tabindex="-1">一份上下文设计清单 <a class="header-anchor" href="#一份上下文设计清单" aria-label="Permalink to &quot;一份上下文设计清单&quot;">​</a></h2><p>设计或排查一个 Agent 时，可以逐项检查：</p><ol><li>稳定的内容（系统提示词、工具定义）是否放在最前面，且每次调用都保持字节级一致？</li><li>每个工具的返回结果有没有长度上限？超长时是截断、摘要，还是存到外部只返回引用？</li><li>历史消息超出预算时，按什么规则裁剪？会不会把 <code>tool_calls</code> 和对应的 <code>tool</code> 消息拆散？</li><li>用户最初的目标和关键约束，在长任务后期是否仍然清晰可见？</li><li>检索到的文档和记忆，是否有相关性阈值？不相关时是否宁可不放？</li><li>能不能把一个&quot;吃上下文&quot;的子任务交给子 Agent，只取回结论？</li><li>有没有记录每一步各部分的 Token 占比，便于定位到底是谁占满了窗口？</li></ol><p>最后一条往往最先被忽略。很多&quot;模型变笨了&quot;的问题，打开 <a href="/guide/14-evaluation/observability">轨迹</a> 一看，是某个工具返回了几万 Token 的原始 HTML。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li>只盯着提示词措辞。花大量时间打磨系统提示词，却放任工具结果把窗口塞满，真正影响效果的是后者。</li><li>窗口够大就不管。窗口上限只是硬约束，远在达到上限之前，成本、延迟和质量就已经开始恶化。</li><li>动态内容放在最前面。把当前时间、用户 ID 写在系统提示词开头，导致每次请求的前缀都不同，缓存完全失效。</li><li>压缩时丢掉关键约束。摘要把&quot;预算不超过 5000 元&quot;这类硬约束概括没了，后续步骤开始违反用户要求。</li><li>检索结果来者不拒。相关性很低的文档也放进来，反而误导模型，参见 <a href="/guide/09-rag/rag-eval">RAG 评估</a>。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><ol><li>上下文工程和提示词工程是什么关系？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>提示词工程是上下文工程的一部分。提示词工程关注单条指令怎么写；上下文工程关注每次模型调用时窗口里的全部内容，包括系统提示词、工具定义、历史、工具结果、检索文档、记忆等，以及它们在多步、多轮中如何选择、裁剪和组织。</p></details><ol start="2"><li>模型的上下文窗口已经很大了，为什么还要主动控制上下文长度？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>三个原因：一是成本和延迟，Agent 每一步都会重发完整上下文，长度直接决定每一步的费用和响应速度；二是注意力稀释，无关内容越多，模型越难利用关键信息，放在中间的信息尤其容易被忽略；三是错误累积，早期的错误或过期信息留在上下文里，会被后续步骤当作事实反复引用。</p></details><ol start="3"><li>&quot;主 Agent 把阅读 10 篇长文档的任务交给子 Agent，只接收总结&quot;属于哪类策略？它的代价是什么？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>属于隔离。好处是主 Agent 的上下文保持精简。代价是信息损失和额外开销：子 Agent 的总结可能漏掉主 Agent 后来才发现需要的细节，而且多一个 Agent 意味着更多调用和协调成本，见 <a href="/guide/12-multi-agent/pitfalls">多 Agent 的坑与成本控制</a>。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">Anthropic：Effective context engineering for AI agents</a></li><li><a href="https://arxiv.org/abs/2307.03172" target="_blank" rel="noreferrer">Lost in the Middle: How Language Models Use Long Contexts（arXiv）</a></li><li><a href="/guide/02-llm-basics/tokens-context">Token 与上下文窗口</a></li><li><a href="/guide/08-memory/memory-types">记忆的分类</a></li></ul>`,40)])])}const g=e(r,[["render",s]]);export{h as __pageData,g as default};
